import random

GROUP = "number_theory"
SKILL = "induction"


def max_distinct_integers(target_sum, min_sum, max_sum, excluded_nums):
    if target_sum == 0:
        return 0

    if target_sum < min_sum:
        return -1

    max_count = 0

    for current_sum in range(min_sum, max_sum + 1):
        if current_sum <= target_sum:
            remaining_sum = target_sum - current_sum
            count = max_distinct_integers(remaining_sum, min_sum, current_sum - 1, excluded_nums)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    target_sum = rng.randint(60, 120)
    min_sum = rng.randint(10, 30)
    max_sum = rng.randint(50, 80)
    excluded_nums = sorted(rng.sample(range(1, target_sum + 1), 10))  # Randomly exclude up to 10 integers

    answer = max_distinct_integers(target_sum, min_sum, max_sum, excluded_nums)

    check = -1
    for current_sum in range(min_sum, max_sum + 1):
        if current_sum <= target_sum:
            remaining_sum = target_sum - current_sum
            count = max_distinct_integers(remaining_sum, min_sum, current_sum - 1, excluded_nums)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Select distinct integers such that the sum of their values ranges from {min_sum} to {max_sum} (inclusive). "
        f"No integer can be excluded, and the sum of all selected integers must exactly match the target sum {target_sum}. "
        f"What is the maximum number of distinct integers that can be selected? State only the integer."
    )
    return problem, str(answer)

