def generate(seed):
    rng = random.Random(seed)
    degree = rng.randint(1, 4)
    coefficients = sorted(rng.sample(range(-10, 11), degree + 1))

    # Generate a polynomial with random coefficients
    def polynomial(x):
        return sum(coeff * (x ** i) for i, coeff in enumerate(coefficients))

    # Calculate the number of distinct roots of the polynomial in the range -10 to 10 inclusive
    roots = {x for x in range(-10, 11) if polynomial(x) == 0}
    answer = len(roots)

    # Independent route: Verify the answer by checking the number of distinct roots using an invariant property
    def invariant_count(x):
        return sum(coeff * (x ** i) for i, coeff in enumerate(coefficients)) == 0

    check_roots = {x for x in range(-10, 11) if invariant_count(x)}
    assert answer == len(check_roots), f"answer={answer} check={len(check_roots)}"

