def max_square_areas(grid_size, min_area_sum, max_area_sum, target_area):
    if target_area == 0:
        return 0

    if target_area < min_area_sum:
        return -1

    max_count = 0

    for area_sum in range(min_area_sum, max_area_sum + 1):
        if area_sum <= target_area:
            remaining_area = target_area - area_sum
            count = max_square_areas(grid_size, min_area_sum, area_sum - 1, remaining_area)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
