            count = max_square_areas(grid_size, min_area_sum, area_sum - 1, remaining_area)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a square grid with side length {grid_size}. Select squares such that the sum of their areas ranges from {min_area_sum} to {max_area_sum} (inclusive). "
